#define UL_RETRY_MS 250u
#define UL_MAX_TRIES 3u
struct ul_frame {unsigned id;uint8_t data[8];};
static inline uint32_t ul_u32(const uint8_t *p){return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}
static inline uint16_t ul_u16(const uint8_t *p){return (uint16_t)((uint16_t)p[0]|((uint16_t)p[1]<<8));}
static inline void ul_put32(uint8_t *p,uint32_t v){for(unsigned i=0;i<4;i++)p[i]=(uint8_t)(v>>(8*i));}
static inline void ul_put16(uint8_t *p,uint16_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);}
static inline uint16_t ul_value(const uint8_t *p){return (uint16_t)(((unsigned)p[6]<<8)|p[7]);}
struct ul_server_node {
    uint32_t cookie,epoch;uint16_t seq,value;unsigned valid,awaiting;
    uint64_t accepted,duplicates,stale,invalid,sessions,seen_ms;
};
static inline uint32_t ul_epoch(uint32_t *counter){++*counter;if(!*counter)++*counter;return *counter;}
/* Return 1 for a response, 0 for silence. modified=1 means a new host write.
 * Caller publishes the committed shadow before transmitting any DATA ACK.
 */
static inline int ul_server_receive(struct ul_server_node *n,unsigned unit,
        uint32_t *counter,const struct ul_frame *in,struct ul_frame *out,
        uint64_t now,unsigned *modified){
    *modified=0;memset(out,0,sizeof *out);
    if(in->id==UL_HELLO+unit){
        uint32_t cookie=ul_u32(in->data);
        if(!cookie||ul_u32(in->data+4)!=UL_MAGIC){n->invalid++;return 0;}
        if(!n->awaiting||cookie!=n->cookie){
            n->cookie=cookie;n->epoch=ul_epoch(counter);n->seq=0;
            n->awaiting=1;n->sessions++;
        }
        out->id=UL_WELCOME+unit;ul_put32(out->data,cookie);ul_put32(out->data+4,n->epoch);return 1;
    }
    if(in->id!=UL_DATA+unit){n->invalid++;return 0;}
    uint32_t epoch=ul_u32(in->data);uint16_t seq=ul_u16(in->data+4),value=ul_value(in->data);
    if(!n->epoch||epoch!=n->epoch){n->stale++;out->id=UL_WELCOME+unit;return 1;} /* zero cookie/epoch requests reconnect */
    if(!seq){n->invalid++;return 0;}
    if(seq==n->seq){
        if(!n->valid||n->value!=value){n->invalid++;return 0;}
        n->duplicates++;
    }else if(seq==(unsigned)n->seq+1u){
        n->seq=seq;n->value=value;n->valid=1;n->awaiting=0;
        n->accepted++;n->seen_ms=now;*modified=1;
    }else if(seq<n->seq){n->stale++;return 0;}
    else {n->invalid++;out->id=UL_WELCOME+unit;return 1;}
    out->id=UL_ACK+unit;memcpy(out->data,in->data,8);return 1;
}
enum ul_phase {UL_CONNECT=1,UL_WAIT_ACK=2,UL_IDLE=3};
struct ul_client {
    unsigned unit,phase,tries,pending;uint32_t cookie,epoch;
    uint16_t seq,value;uint64_t due,acked,unknown,retries,reconnects;
};
static inline void ul_connect(struct ul_client *c,uint64_t now){
    if(!++c->cookie)++c->cookie;
    c->epoch=0;c->seq=0;c->phase=UL_CONNECT;c->tries=0;c->due=now;c->reconnects++;
}
static inline void ul_client_init(struct ul_client *c,unsigned unit,uint64_t now){
    memset(c,0,sizeof *c);c->unit=unit;c->cookie=unit;ul_connect(c,now);
}
static inline void ul_data(const struct ul_client *c,struct ul_frame *out){
    memset(out,0,sizeof *out);out->id=UL_DATA+c->unit;ul_put32(out->data,c->epoch);
    ul_put16(out->data+4,c->seq);out->data[6]=(uint8_t)(c->value>>8);out->data[7]=(uint8_t)c->value;
}
/* Work on a candidate copy. Commit candidate when a proposed frame was
 * submitted successfully, or when no frame was proposed; TX busy must not
 * consume a retry. No busy waits or delays are used by this state machine.
 */
static inline int ul_client_tick(struct ul_client *c,uint64_t now,uint16_t value,struct ul_frame *out){
    if(now<c->due)return 0;
    if(c->phase==UL_IDLE){
        c->value=value;c->pending=1;
        if(c->seq==65535u){ul_connect(c,now);}
        else {c->seq++;c->phase=UL_WAIT_ACK;c->tries=0;}
    }
    if(c->phase==UL_CONNECT){
        if(c->tries==UL_MAX_TRIES){c->tries=0;c->due=now+UL_PERIOD_MS;return 0;}
        memset(out,0,sizeof *out);out->id=UL_HELLO+c->unit;
        ul_put32(out->data,c->cookie);ul_put32(out->data+4,UL_MAGIC);
        c->tries++;c->due=now+UL_RETRY_MS;return 1;
    }
    if(c->phase==UL_WAIT_ACK){
        if(c->tries==UL_MAX_TRIES){
            c->unknown++;c->pending=0;c->phase=UL_IDLE;c->tries=0;c->due=now+UL_PERIOD_MS;return 0;
        }
        if(c->tries)c->retries++;
        ul_data(c,out);c->tries++;c->due=now+UL_RETRY_MS;return 1;
    }
    return 0;
}
static inline void ul_client_receive(struct ul_client *c,const struct ul_frame *in,uint64_t now,uint16_t value){
    if(in->id==UL_WELCOME+c->unit){
        uint32_t cookie=ul_u32(in->data),epoch=ul_u32(in->data+4);
        if(!cookie&&!epoch){if(c->phase==UL_WAIT_ACK)ul_connect(c,now);return;}
        if(c->phase!=UL_CONNECT||cookie!=c->cookie||!epoch)return;
        c->epoch=epoch;c->seq=1;c->phase=UL_WAIT_ACK;c->tries=0;c->due=now;
        if(!c->pending)c->value=value;
        c->pending=1;return;
    }
    if(in->id==UL_ACK+c->unit&&c->phase==UL_WAIT_ACK){
        struct ul_frame expected;ul_data(c,&expected);
        if(memcmp(in->data,expected.data,8))return;
        c->acked++;c->pending=0;c->phase=UL_IDLE;c->due=now+UL_PERIOD_MS;
    }
}
#endif

/* rs_uplink_protocol.h */
#ifndef IGW_RS_UPLINK_PROTOCOL_H
#define IGW_RS_UPLINK_PROTOCOL_H
#include <stdint.h>
#include <string.h>

/* R17: generated latest state, CAN-coordinated ownership, RS485 carries value.
 * RTS(epoch,sequence,magic) carries NO value. GRANT(nonce,epoch).
 * RS ADU: unit,0x41,nonce32LE,epoch32LE,sequence16LE,value16BE,CRC16LE.
 * ACK over CAN: nonce32LE,sequence16LE,value16BE. Not standard Modbus FC.
 */
#define RSU_RTS 0x400u
#define RSU_GRANT 0x440u
#define RSU_ACK 0x480u
#define RSU_DONE 0x4c0u
#define RSU_RELEASED 0x500u
#define RSU_CANCEL 0x540u
#define RSU_DONE_MAGIC 0x1744u
#define RSU_RELEASED_MAGIC 0x1745u
#define RSU_CANCEL_MAGIC 0x1743u
#define RSU_RTS_MAGIC 0x1752u
#define RSU_GRANT_MAGIC 0x1747u
#define RSU_FC 0x41u
#define RSU_BYTES 16u
#define RSU_PERIOD_MS 2000u
#define RSU_RETRY_MS 350u
#define RSU_START_MS 25u
#define RSU_TX_LIMIT_MS 80u
#define RSU_LEASE_MS 200u
#define RSU_TRIES 3u
static inline uint16_t rsu_crc(const uint8_t *p,unsigned n){uint16_t c=0xffff;while(n--){c^=*p++;for(unsigned i=0;i<8;i++)c=(uint16_t)((c>>1)^((c&1)?0xa001:0));}return c;}
static inline void rsu_frame(uint8_t p[RSU_BYTES],unsigned unit,uint32_t nonce,uint32_t epoch,uint16_t seq,uint16_t value){
 memset(p,0,RSU_BYTES);p[0]=(uint8_t)unit;p[1]=RSU_FC;ul_put32(p+2,nonce);ul_put32(p+6,epoch);ul_put16(p+10,seq);p[12]=(uint8_t)(value>>8);p[13]=(uint8_t)value;ul_put16(p+14,rsu_crc(p,14));
}
struct rsu_client {
 unsigned unit,pending,tries,granted,tx_scheduled,release_pending,cancelled;uint32_t epoch,nonce,retired;uint16_t seq,value;
 uint64_t due,grant_ms,accepted,unknown,retries,expired,release_due;
};
static inline void rsu_init(struct rsu_client *c,unsigned unit){memset(c,0,sizeof *c);c->unit=unit;}
/* Called independently of host requests. Candidate is committed on CAN submit. */
static inline int rsu_tick(struct rsu_client *c,uint64_t now,uint32_t epoch,uint16_t value,struct ul_frame *out){
 if(c->release_pending||c->granted)return 0;
 if(c->epoch!=epoch){c->epoch=epoch;c->seq=0;c->pending=c->tries=c->granted=c->tx_scheduled=0;c->nonce=c->retired=0;c->due=now;}
 if(!epoch||now<c->due)return 0;
 if(!c->pending){
  if(c->seq==65535u)return 0; /* caller rekeys CAN session at rollover */
  c->seq++;c->value=value;c->pending=1;c->tries=0;c->nonce=0;
 }
 if(c->tries==RSU_TRIES){c->unknown++;c->pending=c->granted=0;c->due=now+RSU_PERIOD_MS;return 0;}
 memset(out,0,sizeof *out);out->id=RSU_RTS+c->unit;ul_put32(out->data,c->epoch);ul_put16(out->data+4,c->seq);ul_put16(out->data+6,RSU_RTS_MAGIC);
 if(c->tries)c->retries++;
 c->tries++;c->granted=0;c->tx_scheduled=0;c->due=now+RSU_RETRY_MS;return 1;
}
static inline void rsu_receive(struct rsu_client *c,const struct ul_frame *f,uint64_t now){
 uint32_t nonce=ul_u32(f->data);
 if(f->id==RSU_GRANT+c->unit){
  int fresh=!c->retired||(int32_t)(nonce-c->retired)>0;
  if(c->pending&&c->tries&&ul_u32(f->data+4)==c->epoch&&nonce&&fresh&&!c->release_pending&&!c->granted){
   c->nonce=nonce;c->grant_ms=now;c->granted=1;c->tx_scheduled=0;
  }
  return;
 }
 if(ul_u16(f->data+4)!=c->seq)return;
 if(f->id==RSU_RELEASED+c->unit&&c->release_pending&&nonce==c->nonce&&ul_u16(f->data+6)==RSU_RELEASED_MAGIC){
  c->retired=nonce;c->release_pending=c->granted=c->cancelled=0;
  if(c->pending)c->due=now;
  return;
 }
 if(f->id==RSU_CANCEL+c->unit&&nonce&&(nonce==c->nonce||!c->retired||(int32_t)(nonce-c->retired)>0)&&ul_u16(f->data+6)==RSU_CANCEL_MAGIC){
  c->nonce=nonce;c->retired=nonce;c->granted=0;c->cancelled=1;c->release_pending=1;c->release_due=now;return;
 }
 if(!c->pending)return;
 if(f->id==RSU_ACK+c->unit&&c->nonce&&nonce==c->nonce&&ul_value(f->data)==c->value){
  c->accepted++;c->pending=0;c->due=now+RSU_PERIOD_MS;
 }
}
static inline void rsu_done(struct rsu_client *c,uint64_t now){
 c->release_pending=1;c->granted=0;c->retired=c->nonce;c->release_due=now;
}
static inline int rsu_release_tick(struct rsu_client *c,uint64_t now,struct ul_frame *f){
 if(!c->release_pending||now<c->release_due)return 0;
 memset(f,0,sizeof *f);f->id=RSU_DONE+c->unit;ul_put32(f->data,c->nonce);ul_put16(f->data+4,c->seq);ul_put16(f->data+6,RSU_DONE_MAGIC);
 c->release_due=now+250;return 1;
}
/* No grant => no RS transmission. Each grant permits at most one frame. */
static inline int rsu_prepare(struct rsu_client *c,uint64_t now,uint8_t out[RSU_BYTES]){
 if(!c->pending||!c->granted||c->tx_scheduled)return 0;
 if(now<c->grant_ms||now-c->grant_ms>=RSU_START_MS){c->expired++;rsu_done(c,now);return 0;}
 rsu_frame(out,c->unit,c->nonce,c->epoch,c->seq,c->value);c->tx_scheduled=1;return 1;
}
#endif

/* can_common.inc */
/* Generated master/main.c and slave/main.c are complete FD application files.
 * Uses the user's Anlogic CAN SDK. Classical CAN0 at nominal 500 kbit/s.
 * Application MASTER/SLAVE are test roles; CAN itself remains a multi-master bus.
 */
#include <string.h>
#include <stdio.h>
#include <stdint.h>

#include "al_can_hal.h"
#include "al_log.h"
#ifndef CAN0PS_ENABLE
#error "Use igw_can_plat with CAN0 enabled"
#endif
#if CAN0_TYPE != CAN20B || CAN0_SLOW_RATE != 500000
#error "Use CAN0 classical CAN nominal 500k platform"
#endif

#define REQUEST_ID 0x201U
#define REPLY_ID   0x181U
#define REQUEST_TAG 0x43414e00U
#define REPLY_TAG   0x52535000U
#define POLLS 100U
#define WAIT_MS 200U
#define SPIN_LIMIT 10000000U

typedef struct {
    AL_U32 attempts, tx, rx, ok, timeout, tx_fail, rx_error, mismatch, ignored;
    AL_U32 bad_request, config_error, timer_error, rec_max, tec_max;
    AL_U32 koer_seen, busoff_seen, overflow_seen;
    AL_U32 rec, tec, koer, overflow, busoff;
    AL_U64 min_ticks, max_ticks, total_ticks;
} IgwCanStats;
static IgwCanStats Stats;
static AL_CAN_HalStruct *Can;
static AL_U64 TimerHz;
static AL_CAN_InitStruct Config = {
    .Protocol = AL_CAN_TYPE_2_0B,
    .TxIntrMode = AL_CAN_RUN_POLLING,
    .RxIntrMode = AL_CAN_RUN_POLLING,
    .SlowBitRate = AL_CAN_ARBITRATION_0_5M,
    .FastBitRate = AL_CAN_ARBITRATION_0_5M
};
static AL_U64 Now(AL_VOID) { return AlSys_GetTimerTickCount(); }
static AL_U64 Budget(AL_U32 ms) { return (TimerHz * ms + 999U) / 1000U; }
static AL_U32 Us(AL_U64 ticks) { return (AL_U32)(ticks * 1000000ULL / TimerHz); }

static AL_VOID Snapshot(AL_BOOL print)
{
    AL_REG base = Can->Dev.BaseAddr;
    AL_U32 rec = AL_REG32_GET_BITS(base + CAN_TECNT_REVNT_TDC_EALCAP_OFFSET,
        CAN_TECNT_REVNT_TDC_EALCAP_RECNT_SHIFT, CAN_TECNT_REVNT_TDC_EALCAP_RECNT_SIZE);
    AL_U32 tec = AL_REG32_GET_BITS(base + CAN_TECNT_REVNT_TDC_EALCAP_OFFSET,
        CAN_TECNT_REVNT_TDC_EALCAP_TECNT_SHIFT, CAN_TECNT_REVNT_TDC_EALCAP_TECNT_SIZE);
    AL_U32 koer = AlCan_ll_GetKoer(base);
    AL_U32 overflow = AL_REG32_GET_BIT(base + CAN_RCTRL_TCTRL_TCMD_CFG_STAT_OFFSET,
        CAN_RCTRL_TCTRL_TCMD_CFG_STAT_ROV_SHIFT);
    AL_U32 busoff = AlCan_ll_IsBusOff(base);
    Stats.rec=rec;Stats.tec=tec;Stats.koer=koer;Stats.overflow=overflow;Stats.busoff=busoff;
    if (rec > Stats.rec_max) Stats.rec_max = rec;
    if (tec > Stats.tec_max) Stats.tec_max = tec;
    Stats.koer_seen |= koer ? 1U << koer : 0U;
    Stats.overflow_seen |= overflow;
    Stats.busoff_seen |= busoff;
    if (print) AL_LOG(AL_LOG_LEVEL_NOTICE,
        "[CAN-HW] REC=%u TEC=%u KOER=%u overflow=%u busoff=%u\r\n",
        rec, tec, koer, overflow, busoff);
}

static AL_S32 Setup(AL_VOID)
{
    TimerHz = AlSys_GetTimerFreq();
    if (TimerHz < 1000ULL || TimerHz > 1000000000ULL) {
        ++Stats.timer_error; return (AL_S32)AL_CAN_ERR_ILLEGAL_PARAM;
    }
    AL_S32 ret = AlCan_Hal_Init(&Can, 0, &Config, AL_NULL);
    if (ret != AL_OK || !Can) { ++Stats.config_error; return ret != AL_OK ? ret : (AL_S32)AL_CAN_ERR_NULL_PTR; }
    AL_REG base = Can->Dev.BaseAddr;
    if (base != CAN0__BASE_ADDR) { ++Stats.config_error; return (AL_S32)AL_CAN_ERR_ILLEGAL_PARAM; }
    /* The SDK Init defaults to internal loopback. Explicitly replace it while
     * reset is asserted. This avoids an SDK config-mode busy-wait with no deadline.
     * No TX is submitted until all mode/timing fields have been checked below. */
    AlCan_ll_ClrIntr(base, AL_CAN_INTR_MASK_EN_ALL);
    AlCan_ll_SetCanCtrlReset(base, AL_TRUE);
    AlCan_ll_SetLbmi(base, AL_FALSE);
    AlCan_ll_SetLbme(base, AL_FALSE);
    AlCan_ll_SetLom(base, AL_FALSE);
    AlCan_ll_SetStby(base, AL_FALSE);
    AlCan_ll_SetSack(base, AL_CAN_SACK_NO_SELF_ACK);
    /* v1.2: disabled acceptance filters reject RX; they are NOT accept-all.
     * Enable filter 0 for every standard ID; application validates ID/tag/seq.
     * For this core mask bit 1 ignores the corresponding ID bit. */
    for (AL_U32 filter = 0; filter < 3U; ++filter) AlCan_ll_SetAcfenx(base, filter, AL_FALSE);
    Can->Dev.Host.OpsMode = AL_CAN_MODE_CONFIG;
    AL_CAN_FilterCfgStruct filter_cfg = {
        .FilterEn = AL_TRUE, .FilterIndex = AL_CAN_FILTER_0,
        .MaskType = AL_CAN_FILTER_MASK_STD,
        .MaskValue = 0x1fffffffU, .IdValue = 0U
    };
    ret = AlCan_Dev_SetFilter(&Can->Dev, &filter_cfg);
    if (ret != AL_OK) { ++Stats.config_error; return ret; }
    AlCan_ll_SetAcfadr(base, AL_CAN_FILTER_0);
    AlCan_ll_SetSelmask(base, AL_CAN_SELMASK_ACCEPT_MASK);
    DSB();
    AL_U32 filter_mask = AlCan_ll_ReadAcodexAmaskx(base);
    AlCan_ll_SetSelmask(base, AL_CAN_SELMASK_ACCEPT_CODE);
    DSB();
    AL_U32 filter_code = AlCan_ll_ReadAcodexAmaskx(base);
    AL_U32 expected_mask = filter_cfg.MaskValue |
        ((AL_U32)filter_cfg.MaskType << CAN_ACF_3_ACF_2_ACF_1_ACF_0_AIDE_SHIFT);
    if (AlCan_ll_IsAcfen(base) != 1U || filter_mask != expected_mask || filter_code != 0U) {
        AL_LOG(AL_LOG_LEVEL_NOTICE,
            "[CAN-FILTER] readback FAILED enabled=0x%x mask=0x%08x code=0x%08x\r\n",
            AlCan_ll_IsAcfen(base), filter_mask, filter_code);
        ++Stats.config_error; return (AL_S32)AL_CAN_ERR_ILLEGAL_PARAM;
    }
    Can->Dev.Host.OpsMode = AL_CAN_MODE_NORMAL;
    AlCan_ll_SetCanCtrlReset(base, AL_FALSE);
    /* v1.1: set TPSS AFTER reset release. On the user's cold boot the earlier
     * write during reset read back as zero. Keep the readback guard below;
     * do not silently permit persistent TX retries when TPSS does not latch. */
    DSB();
    AlSys_MDelay(1);
    AlCan_ll_SetTpss(base, AL_TRUE);
    DSB();
    AL_U32 fd = AL_REG32_GET_BIT(CAN_TOP_CFG_CTRL_ADDR, CAN_TOP_CFG_CTRL_ADDR_CAN0_FD_ENABLE_SHIFT);
    AL_U32 lbmi = AlCan_ll_IsLbmiEnabled(base), lbme = AlCan_ll_IsLbmeEnabled(base);
    AL_U32 lom = AlCan_ll_IsLom(base), stby = AlCan_ll_IsStby(base);
    AL_U32 sack = AL_REG32_GET_BIT(base + CAN_RCTRL_TCTRL_TCMD_CFG_STAT_OFFSET,
                                   CAN_RCTRL_TCTRL_TCMD_CFG_STAT_SACK_SHIFT);
    AL_U32 shot = AL_REG32_GET_BIT(base + CAN_RCTRL_TCTRL_TCMD_CFG_STAT_OFFSET,
                                   CAN_RCTRL_TCTRL_TCMD_CFG_STAT_TPSS_SHIFT);
    AL_U32 seg1 = AlCan_ll_GetSseg1(base)+2U, seg2 = AlCan_ll_GetSseg2(base)+1U;
    AL_U32 sjw = AlCan_ll_GetSsjw(base)+1U, presc = AlCan_ll_GetSpresc(base)+1U;
    AL_U32 filter_enabled = AlCan_ll_IsAcfen(base);
    AL_LOG(AL_LOG_LEVEL_NOTICE,
        "[CAN-FILTER] enabled=0x%x mask_raw=0x%08x code=0x%08x accept=ALL_STD\r\n",
        filter_enabled, filter_mask, filter_code);
    AL_LOG(AL_LOG_LEVEL_NOTICE,
        "[CAN-MODE] fd=%u internal=%u external=%u listen=%u standby=%u self_ack=%u single_shot=%u\r\n",
        fd, lbmi, lbme, lom, stby, sack, shot);
    AL_LOG(AL_LOG_LEVEL_NOTICE,
        "[CAN-TIMING] seg1=%u seg2=%u sjw=%u prescaler=%u target=500000 timer=%u\r\n",
        seg1, seg2, sjw, presc, (AL_U32)TimerHz);
    if (filter_enabled!=1U || fd || lbmi || lbme || lom || stby || sack || !shot || seg1!=64U || seg2!=16U || sjw!=16U || presc!=2U ||
        Can->Dev.Host.InputClk!=80000000U || Can->Dev.Host.Protocol!=AL_CAN_TYPE_2_0B ||
        Can->Dev.Host.TxIntrMode!=AL_CAN_RUN_POLLING || Can->Dev.Host.RxIntrMode!=AL_CAN_RUN_POLLING) {
        ++Stats.config_error; return (AL_S32)AL_CAN_ERR_ILLEGAL_PARAM;
    }
    Snapshot(AL_TRUE);
    return AL_OK;
}

static AL_VOID Frame(AL_CAN_FrameStruct *frame, AL_U32 id, AL_U32 seq, AL_U32 tag)
{
    memset(frame, 0, sizeof(*frame));
    frame->BufferMode=AL_CAN_BUFFER_MODE_PTB; frame->Id=id; frame->DataLen=AL_CAN_LEN_8;
    frame->Data[0]=seq; frame->Data[1]=tag^seq;
}
static AL_BOOL Valid(const AL_CAN_FrameStruct *frame, AL_U32 tag)
{
    return frame->DataLen==AL_CAN_LEN_8 && !frame->IsIdExt && !frame->IsRemote &&
        !frame->IsBitSwitch && frame->Koer==AL_CAN_KOER_NONE && frame->Data[0]!=0U &&
        frame->Data[1]==(tag^frame->Data[0]);
}

static AL_S32 Receive(AL_CAN_FrameStruct *frame)
{
    memset(frame,0,sizeof(*frame));
    AL_S32 ret=AlCan_Hal_RecvFrame(Can,frame);
    if(ret==AL_OK) ++Stats.rx;
    else if(ret!=AL_CAN_ERR_RECV_EMPTY) {
        ++Stats.rx_error;
        /* The supplied driver leaves KOER-error frames at the FIFO head. */
        if(ret==AL_CAN_ERR_RECV) AlCan_ll_SetRrel(Can->Dev.BaseAddr,AL_CAN_RREL_RELEASE);
    }
    return ret;
}
static AL_VOID Summary(AL_VOID)
{
    Snapshot(AL_TRUE);
    AL_LOG(AL_LOG_LEVEL_NOTICE,
        "[CAN-STATS] attempts=%u tx_submit=%u rx=%u ok=%u timeout=%u tx_fail=%u rx_error=%u mismatch=%u ignored=%u bad_request=%u\r\n",
        Stats.attempts,Stats.tx,Stats.rx,Stats.ok,Stats.timeout,Stats.tx_fail,Stats.rx_error,
        Stats.mismatch,Stats.ignored,Stats.bad_request);
    AL_LOG(AL_LOG_LEVEL_NOTICE,
        "[CAN-STATS] config_error=%u timer_error=%u REC_max=%u TEC_max=%u KOER_seen=0x%x overflow_seen=%u busoff_seen=%u\r\n",
        Stats.config_error,Stats.timer_error,Stats.rec_max,Stats.tec_max,Stats.koer_seen,
        Stats.overflow_seen,Stats.busoff_seen);
    if(Stats.ok && IGW_CAN_MASTER) AL_LOG(AL_LOG_LEVEL_NOTICE,
        "[CAN-RTT] min=%u avg=%u max=%u us (request start to PS reply read)\r\n",
        Us(Stats.min_ticks),Us(Stats.total_ticks/Stats.ok),Us(Stats.max_ticks));
}
static AL_BOOL Clean(AL_VOID)
{
    return !(Stats.timeout||Stats.tx_fail||Stats.rx_error||Stats.mismatch||Stats.bad_request||
        Stats.config_error||Stats.timer_error||Stats.rec_max||Stats.tec_max||Stats.koer_seen||
        Stats.overflow_seen||Stats.busoff_seen);
}

/* rtu_common.inc */
#define IGW_LOG(...) AL_LOG(AL_LOG_LEVEL_NOTICE,__VA_ARGS__)
#define IGW_BASE ((uintptr_t)0x80100000U)
static igw_device Rtu;
static igw_counters RtuBaseline;
static igw_udp_metrics RtuStats;
static AL_U64 RtuMin,RtuMax,RtuSum,BootTick;
static AL_U64 Microseconds(AL_U64 ticks)
{
    return ticks/TimerHz*1000000ULL+(ticks%TimerHz)*1000000ULL/TimerHz;
}
static uint64_t BoardUs(void *opaque) { (void)opaque;return Microseconds(Now()); }
#ifdef IGW_HOST_TEST
uint32_t igw_host_read(unsigned offset);
void igw_host_write(unsigned offset,uint32_t value);
static uint32_t BoardRead(void *opaque,unsigned offset){(void)opaque;return igw_host_read(offset);}
static void BoardWrite(void *opaque,unsigned offset,uint32_t value){(void)opaque;igw_host_write(offset,value);}
#else
static uint32_t BoardRead(void *opaque,unsigned offset)
{
    (void)opaque;DSB();uint32_t v=*(volatile uint32_t *)(IGW_BASE+offset);DSB();return v;
}
static void BoardWrite(void *opaque,unsigned offset,uint32_t value)
{
    (void)opaque;DSB();*(volatile uint32_t *)(IGW_BASE+offset)=value;DSB();
}
#endif
/* Bounded, cooperative RS485 TX. No busy wait during the runtime. */
static struct {
    unsigned phase;
    uint8_t bytes[256];size_t length;
    uint32_t before;
    AL_U64 started,feed,latest_start,latest_finish;
} RtuTx;
static int RtuTxBegin(const uint8_t *p,size_t n)
{
    if (RtuTx.phase || !p || n<4U || n>256U) return IGW_BAD_LENGTH;
    memcpy(RtuTx.bytes,p,n);RtuTx.length=n;RtuTx.phase=1;RtuTx.started=BoardUs(NULL);RtuTx.latest_start=RtuTx.latest_finish=0;
    return IGW_OK;
}
/* 0=waiting, 1=completed, -1=failed. Every exit revokes TX authorization. */
static int RtuTxTick(void)
{
    if (!RtuTx.phase) return 0;
    AL_U64 now=BoardUs(NULL);uint32_t s=igw_rd(&Rtu,IGW_STATUS);
    if (RtuTx.phase==2 && igw_rd(&Rtu,IGW_TX_COUNT)!=RtuTx.before && !(s&IGW_TX_BUSY)) {
        igw_wr(&Rtu,IGW_CONTROL,0);RtuTx.phase=0;return 1;
    }
    if ((RtuTx.phase==1 && RtuTx.latest_start && now>=RtuTx.latest_start) ||
        (RtuTx.latest_finish && now>=RtuTx.latest_finish) || now-RtuTx.started>=200000ULL) {
        igw_wr(&Rtu,IGW_CONTROL,0);RtuTx.phase=0;return -1;
    }
    if (RtuTx.phase==1 && !(s&IGW_TX_BUSY) && (s&IGW_QUIET)) {
        for (unsigned i=0;i<RtuTx.length;i+=4) {
            uint32_t v=0;
            for (unsigned b=0;b<4 && i+b<RtuTx.length;++b)v|=(uint32_t)RtuTx.bytes[i+b]<<(8*b);
            igw_wr(&Rtu,IGW_TX_DATA+i,v);
        }
        igw_wr(&Rtu,IGW_TX_LEN,(uint32_t)RtuTx.length);RtuTx.before=igw_rd(&Rtu,IGW_TX_COUNT);
        s=igw_rd(&Rtu,IGW_STATUS);
        if ((s&IGW_TX_BUSY) || !(s&IGW_QUIET)) return 0;
        igw_wr(&Rtu,IGW_FEED,0x4b49434bU);igw_wr(&Rtu,IGW_CONTROL,1);
        RtuTx.feed=now;igw_wr(&Rtu,IGW_TX_KICK,1);RtuTx.phase=2;
    } else if (RtuTx.phase==2 && now-RtuTx.feed>=Rtu.feed_interval_us) {
        igw_wr(&Rtu,IGW_FEED,0x4b49434bU);RtuTx.feed=now;
    }
    return 0;
}
static AL_BOOL RtuClean(void)
{
    igw_counters c=igw_counter_delta(igw_get_counters(&Rtu),RtuBaseline);
    return !(RtuStats.timeouts||RtuStats.tx_fail||RtuStats.exceptions||RtuStats.mismatches||RtuStats.sw_bad||
        c.crc||c.uart||c.gap||c.overrun||c.watchdog);
}
static void RtuSummary(void)
{
    igw_counters c=igw_counter_delta(igw_get_counters(&Rtu),RtuBaseline);
    IGW_LOG("[RS485] attempts=%u ok=%u timeout=%u tx_fail=%u exception=%u mismatch=%u sw_bad=%u\r\n",
        RtuStats.attempts,RtuStats.ok,RtuStats.timeouts,RtuStats.tx_fail,RtuStats.exceptions,RtuStats.mismatches,RtuStats.sw_bad);
    IGW_LOG("[PL-RS485] good=%u tx=%u crc=%u uart=%u gap=%u overrun=%u wd=%u\r\n",
        c.good,c.tx,c.crc,c.uart,c.gap,c.overrun,c.watchdog);
    if (IGW_CAN_MASTER && RtuStats.ok)IGW_LOG("[RS485-RTT] min=%u avg=%u max=%u us\r\n",
        (unsigned)RtuMin,(unsigned)(RtuSum/RtuStats.ok),(unsigned)RtuMax);
}

/* slave.inc */
static struct igw_nodes Nodes;
static struct {AL_BOOL pending;AL_CAN_FrameStruct frame;AL_U64 started;} CanReply;
static struct ul_client Uplink[IGW_NODE_COUNT];
static unsigned UplinkNext,RsUplinkNext;
static struct rsu_client RsUplink[IGW_NODE_COUNT];
static unsigned RsUplinkTx;
static uint64_t UplinkMs(void){return Microseconds(Now()-BootTick)/1000;}
static uint16_t UplinkSource(unsigned i,uint64_t now){
    uint16_t value=(uint16_t)((IGW_FIRST_NODE+i)*1000u+now/1000);
    Nodes.regs[i][11]=value;return value; /* generated device-local test counter */
}
static void UplinkInit(void){
    UplinkNext=RsUplinkNext=RsUplinkTx=0;uint64_t now=UplinkMs();
    for(unsigned i=0;i<IGW_NODE_COUNT;i++){ul_client_init(Uplink+i,IGW_FIRST_NODE+i,now);rsu_init(RsUplink+i,IGW_FIRST_NODE+i);}
}
static int UplinkReceive(const AL_CAN_FrameStruct *f){
    unsigned unit=f->Id>UL_WELCOME&&f->Id<=UL_WELCOME+16?f->Id-UL_WELCOME:
        f->Id>UL_ACK&&f->Id<=UL_ACK+16?f->Id-UL_ACK:
        f->Id>RSU_GRANT&&f->Id<=RSU_GRANT+16?f->Id-RSU_GRANT:
        f->Id>RSU_ACK&&f->Id<=RSU_ACK+16?f->Id-RSU_ACK:
        f->Id>RSU_RELEASED&&f->Id<=RSU_RELEASED+16?f->Id-RSU_RELEASED:
        f->Id>RSU_CANCEL&&f->Id<=RSU_CANCEL+16?f->Id-RSU_CANCEL:0;
    int i=igw_node_index(unit);if(i<0)return 0;
    if(f->DataLen!=AL_CAN_LEN_8||f->IsIdExt||f->IsRemote||f->IsBitSwitch||f->Koer!=AL_CAN_KOER_NONE)return 1;
    struct ul_frame frame;frame.id=f->Id;
    for(unsigned b=0;b<8;b++)frame.data[b]=(uint8_t)(f->Data[b/4]>>(8*(b%4)));
    uint64_t now=UplinkMs();if(f->Id>RSU_GRANT){rsu_receive(RsUplink+i,&frame,now);return 1;}
    ul_client_receive(Uplink+i,&frame,now,UplinkSource((unsigned)i,now));return 1;
}
static void UplinkTick(void){
    if(CanReply.pending)return; /* existing command responses have priority */
    uint64_t now=UplinkMs();
    for(unsigned budget=0;budget<IGW_NODE_COUNT;budget++){
        unsigned i=UplinkNext;UplinkNext=(UplinkNext+1)%IGW_NODE_COUNT;
        struct ul_client candidate=Uplink[i];struct ul_frame frame;
        if(!ul_client_tick(&candidate,now,UplinkSource(i,now),&frame)){Uplink[i]=candidate;continue;}
        AL_CAN_FrameStruct tx;memset(&tx,0,sizeof tx);tx.BufferMode=AL_CAN_BUFFER_MODE_PTB;
        tx.Id=frame.id;tx.DataLen=AL_CAN_LEN_8;
        for(unsigned b=0;b<8;b++)tx.Data[b/4]|=(AL_U32)frame.data[b]<<(8*(b%4));
        if(AlCan_Hal_SendFrame(Can,&tx)==AL_OK)Uplink[i]=candidate;
        return; /* bounded, no UART/CAN busy wait */
    }
}
static void RsUplinkTick(void){
    uint64_t now=UplinkMs();
    for(unsigned b=0;b<IGW_NODE_COUNT;b++){
        unsigned i=RsUplinkNext;RsUplinkNext=(RsUplinkNext+1)%IGW_NODE_COUNT;
        struct rsu_client *c=RsUplink+i;uint8_t frame[RSU_BYTES];
        if(c->cancelled&&RsUplinkTx==i+1){
            igw_wr(&Rtu,IGW_CONTROL,0);
            if(RtuTx.phase==1){RtuTx.phase=0;RsUplinkTx=0;}
        }
        if(!RtuTx.phase && !(igw_rd(&Rtu,IGW_STATUS)&IGW_RX_READY) && rsu_prepare(c,now,frame)){
            if(RtuTxBegin(frame,sizeof frame)==IGW_OK){
                /* Absolute deadlines retain the original grant receipt time. */
                AL_U64 origin=BoardUs(NULL)-(now-c->grant_ms)*1000ULL;
                RtuTx.latest_start=origin+RSU_START_MS*1000ULL;
                RtuTx.latest_finish=origin+RSU_TX_LIMIT_MS*1000ULL;RsUplinkTx=i+1;
            }
        }
        if(CanReply.pending)continue;
        if(c->seq==65535u&&!c->pending)ul_connect(Uplink+i,now);
        struct rsu_client candidate=*c;struct ul_frame f;
        uint32_t epoch=Uplink[i].phase==UL_CONNECT?0:Uplink[i].epoch;
        uint16_t source=(uint16_t)((IGW_FIRST_NODE+i)*1000u+now/1000);
        Nodes.regs[i][12]=source;
        int release=0;
        if(!RtuTx.phase && !(igw_rd(&Rtu,IGW_STATUS)&IGW_TX_BUSY) && (igw_rd(&Rtu,IGW_STATUS)&IGW_QUIET))release=rsu_release_tick(&candidate,now,&f);
        if(!release&&!rsu_tick(&candidate,now,epoch,source,&f)){*c=candidate;continue;}
        AL_CAN_FrameStruct tx;memset(&tx,0,sizeof tx);tx.BufferMode=AL_CAN_BUFFER_MODE_PTB;
        tx.Id=f.id;tx.DataLen=AL_CAN_LEN_8;
        for(unsigned k=0;k<8;k++)tx.Data[k/4]|=(AL_U32)f.data[k]<<(8*(k%4));
        if(AlCan_Hal_SendFrame(Can,&tx)==AL_OK)*c=candidate;
        return;
    }
}
static void CanTick(void)
{
    if(CanReply.pending){
        AL_S32 ret=AlCan_Hal_SendFrame(Can,&CanReply.frame);
        if(ret==AL_OK){++Stats.tx;++Stats.ok;CanReply.pending=AL_FALSE;}
        else if((ret!=AL_CAN_ERR_TP_BUSY && ret!=AL_CAN_ERR_IN_TS_FULL && ret!=AL_CAN_ERR_BUSY) ||
                Now()-CanReply.started>=Budget(WAIT_MS)){++Stats.tx_fail;CanReply.pending=AL_FALSE;}
    }
    if(CanReply.pending)return;
    for(unsigned i=0;i<4;++i){
        AL_CAN_FrameStruct request;AL_S32 ret=Receive(&request);
        if(ret==AL_CAN_ERR_RECV_EMPTY)break;
        if(ret!=AL_OK)break;
        if(UplinkReceive(&request))continue;
        if(request.Id>=0x211 && request.Id<=0x220 && igw_node_index(request.Id-0x210)>=0) {
            if(request.DataLen!=AL_CAN_LEN_8 || request.IsIdExt || request.IsRemote ||
               request.IsBitSwitch || request.Koer!=AL_CAN_KOER_NONE) {++Stats.bad_request;continue;}
            uint8_t p[8],out[8];
            for(unsigned b=0;b<8;b++)p[b]=(uint8_t)(request.Data[b/4]>>(8*(b%4)));
            int reply_id=igw_nodes_can(&Nodes,request.Id,p,out,Microseconds(Now()-BootTick));
            memset(&CanReply.frame,0,sizeof CanReply.frame);
            CanReply.frame.BufferMode=AL_CAN_BUFFER_MODE_PTB;
            CanReply.frame.Id=(AL_U32)reply_id;CanReply.frame.DataLen=AL_CAN_LEN_8;
            for(unsigned b=0;b<8;b++)CanReply.frame.Data[b/4]|=(AL_U32)out[b]<<(8*(b%4));
            ++Stats.attempts;CanReply.pending=AL_TRUE;CanReply.started=Now();break;
        }
        if(request.Id!=REQUEST_ID || igw_node_index(1)<0){++Stats.ignored;continue;}
        if(!Valid(&request,REQUEST_TAG)){++Stats.bad_request;continue;}
        ++Stats.attempts;Frame(&CanReply.frame,REPLY_ID,request.Data[0],REPLY_TAG);
        CanReply.pending=AL_TRUE;CanReply.started=Now();break;
    }
}
static void RtuTick(void)
{
    if(RtuTx.phase){int done=RtuTxTick();
        if(RsUplinkTx){if(done){rsu_done(RsUplink+RsUplinkTx-1,UplinkMs());RsUplinkTx=0;}} /* Separate upload statistics, no false Modbus completions. */
        else if(done<0)++RtuStats.tx_fail;else if(done>0)++RtuStats.ok;
        return;}
    uint8_t rx[256],reply[256];size_t n=0;uint64_t ticks=0;
    int got=igw_take_frame(&Rtu,rx,&n,&ticks);
    if(got<0){++RtuStats.sw_bad;return;}if(got==0)return;
    if(n && igw_node_index(rx[0])>=0)++RtuStats.attempts;
    size_t length=igw_nodes_rtu(&Nodes,rx,n,reply,Microseconds(Now()-BootTick));
    if(length && RtuTxBegin(reply,length)!=IGW_OK)++RtuStats.tx_fail;
}
static void RunDual(void)
{
    IGW_LOG("[DUAL-SLAVE] R17 READY first_node=%u nodes=%u; independent banks; CAN request=0x210+unit reply=0x190+unit; RS485 FC03+FC06 9600 8E1\r\n",IGW_FIRST_NODE,IGW_NODE_COUNT);
    IGW_LOG("[UPLINK] R17 CAN host R16; RS485 host R17 with CAN RTS/GRANT/ACK, 2s generated counters; no unsolicited RS485 without lease\r\n");
    AL_U64 last_log=Now();
    for(;;){
        CanTick();RtuTick();UplinkTick();RsUplinkTick();
        if(Now()-last_log>=Budget(5000) && !CanReply.pending && !RtuTx.phase){Summary();RtuSummary();
            for(unsigned i=0;i<IGW_NODE_COUNT;i++)IGW_LOG("[UPLINK] unit=%u acked=%llu retries=%llu unknown=%llu reconnects=%llu\r\n",IGW_FIRST_NODE+i,(unsigned long long)Uplink[i].acked,(unsigned long long)Uplink[i].retries,(unsigned long long)Uplink[i].unknown,(unsigned long long)Uplink[i].reconnects);
            for(unsigned i=0;i<IGW_NODE_COUNT;i++)IGW_LOG("[RS-UPLINK] unit=%u acked=%llu retries=%llu unknown=%llu expired=%llu\r\n",IGW_FIRST_NODE+i,(unsigned long long)RsUplink[i].accepted,(unsigned long long)RsUplink[i].retries,(unsigned long long)RsUplink[i].unknown,(unsigned long long)RsUplink[i].expired);
            IGW_LOG("[DUAL-SLAVE] %s; CAN ok is reply-submit, check master/PC\r\n",(Clean()&&RtuClean())?"CLEAN":"REVIEW");last_log=Now();}
#ifdef IGW_HOST_TEST
        if(Stats.ok>=100 && RtuStats.ok>=100)break;
#endif
    }
}

/* main.inc */
AL_S32 main(AL_VOID)
{
    memset(&Stats,0,sizeof Stats);memset(&RtuStats,0,sizeof RtuStats);memset(&RtuTx,0,sizeof RtuTx);
    AlLog_SetLevel(AL_LOG_LEVEL_NOTICE);Can=AL_NULL;
    IGW_LOG("\r\n[IGW-DUAL] gateway UPLINK_R17 role=%s CAN(v1.2)+RS485+UDP\r\n",IGW_CAN_MASTER?"MASTER":"SLAVE");
    IGW_LOG("[PLATFORM] HPF=%s BIT_METADATA=%s\r\n",HPF_EXPORT_TIME,BITSTREAM_GENERATE_TIME);
    AL_S32 ret=Setup();if(ret!=AL_OK)goto stop;
    BootTick=Now();for(unsigned i=0;i<100;++i)(void)Now();
    if(Now()==BootTick){++Stats.timer_error;ret=(AL_S32)AL_CAN_ERR_ILLEGAL_PARAM;goto stop;}
    memset(&Rtu,0,sizeof Rtu);Rtu.read=BoardRead;Rtu.write=BoardWrite;Rtu.now_us=BoardUs;
    IGW_LOG("[PL-RS485] magic=0x%08x version=0x%08x clock=%u Hz\r\n",
        igw_rd(&Rtu,IGW_MAGIC),igw_rd(&Rtu,IGW_VERSION),igw_rd(&Rtu,IGW_CLOCK));
    ret=(AL_S32)igw_configure(&Rtu,9600);if(ret!=IGW_OK)goto stop;
    RtuBaseline=igw_get_counters(&Rtu);
    IGW_LOG("[RS485-CONFIG] 9600 8E1 multi-node base=0x80100000 div=%u\r\n",igw_rd(&Rtu,IGW_DIV));
#if IGW_CAN_MASTER
    memset(&Net,0,sizeof Net);memset(&CanJob,0,sizeof CanJob);memset(&RtuJob,0,sizeof RtuJob);PollEnabled=AL_FALSE;
    Udp=AL_NULL;ret=NetworkInit();if(ret!=AL_OK)goto stop;
#else
    memset(&CanReply,0,sizeof CanReply);igw_nodes_init(&Nodes);UplinkInit();
#endif
    RunDual();return AL_OK;
stop:
    IGW_LOG("[FATAL] dual init ret=0x%08x; no polling started\r\n",(AL_U32)ret);
    if(Can)AlCan_ll_SetCanCtrlReset(Can->Dev.BaseAddr,AL_TRUE);
#ifndef IGW_HOST_TEST
    for(;;)AlSys_MDelay(1000);
#endif
    return ret;
}
